from pathlib import Path
root=Path('/mnt/data/v113_work')

# 1) Prisma schema: comment likes + admin hearts + reply metadata.
p=root/'backend/prisma/schema.prisma'
s=p.read_text()
s=s.replace('  reelComments        ReelComment[]         @relation("UserReelComments")\n', '  reelComments        ReelComment[]         @relation("UserReelComments")\n  commentLikes        CommentLike[]         @relation("UserCommentLikes")\n  reelCommentLikes    ReelCommentLike[]     @relation("UserReelCommentLikes")\n')
s=s.replace('  body      String\n  createdAt DateTime @default(now())\n  editedAt DateTime?\n  editCount Int @default(0)\n  post      Post', '  body      String\n  parentId  String?\n  adminLikes Int @default(0)\n  createdAt DateTime @default(now())\n  editedAt DateTime?\n  editCount Int @default(0)\n  post      Post')
s=s.replace('  author    User     @relation("UserComments", fields: [authorId], references: [id], onDelete: Cascade)\n\n  @@index([postId, createdAt])\n}\n\nmodel Like {', '  author    User     @relation("UserComments", fields: [authorId], references: [id], onDelete: Cascade)\n  likes     CommentLike[] @relation("CommentLikes")\n\n  @@index([postId, createdAt])\n  @@index([postId, adminLikes])\n}\n\nmodel CommentLike {\n  commentId String\n  userId    String\n  createdAt DateTime @default(now())\n  comment   Comment @relation("CommentLikes", fields: [commentId], references: [id], onDelete: Cascade)\n  user      User @relation("UserCommentLikes", fields: [userId], references: [id], onDelete: Cascade)\n  @@id([commentId, userId])\n  @@index([commentId, createdAt])\n}\n\nmodel Like {')
s=s.replace('  body String\n  createdAt DateTime @default(now())\n  editedAt DateTime?\n  editCount Int @default(0)\n  reel @relation', '  body String\n  parentId String?\n  adminLikes Int @default(0)\n  createdAt DateTime @default(now())\n  editedAt DateTime?\n  editCount Int @default(0)\n  reel @relation')
s=s.replace('  author User @relation("UserReelComments", fields:[authorId], references:[id], onDelete:Cascade)\n  @@index([reelId,createdAt])\n}\n\nmodel ReelFeedback', '  author User @relation("UserReelComments", fields:[authorId], references:[id], onDelete:Cascade)\n  likes ReelCommentLike[] @relation("ReelCommentLikes")\n  @@index([reelId,createdAt])\n  @@index([reelId,adminLikes])\n}\n\nmodel ReelCommentLike {\n  commentId String\n  userId String\n  createdAt DateTime @default(now())\n  comment ReelComment @relation("ReelCommentLikes", fields:[commentId], references:[id], onDelete:Cascade)\n  user User @relation("UserReelCommentLikes", fields:[userId], references:[id], onDelete:Cascade)\n  @@id([commentId,userId])\n  @@index([commentId,createdAt])\n}\n\nmodel ReelFeedback')
p.write_text(s)

# 2) Server schema compatibility additions.
p=root/'backend/src/server.js'
s=p.read_text()
needle='    `ALTER TABLE "Episode" ADD COLUMN IF NOT EXISTS "adminViews" INTEGER NOT NULL DEFAULT 0`,\n'
insert='''    `ALTER TABLE "Comment" ADD COLUMN IF NOT EXISTS "parentId" TEXT`,\n    `ALTER TABLE "Comment" ADD COLUMN IF NOT EXISTS "adminLikes" INTEGER NOT NULL DEFAULT 0`,\n    `ALTER TABLE "ReelComment" ADD COLUMN IF NOT EXISTS "parentId" TEXT`,\n    `ALTER TABLE "ReelComment" ADD COLUMN IF NOT EXISTS "adminLikes" INTEGER NOT NULL DEFAULT 0`,\n    `CREATE TABLE IF NOT EXISTS "CommentLike" ("commentId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("commentId","userId"))`,\n    `CREATE INDEX IF NOT EXISTS "CommentLike_commentId_createdAt_idx" ON "CommentLike"("commentId","createdAt")`,\n    `CREATE TABLE IF NOT EXISTS "ReelCommentLike" ("commentId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("commentId","userId"))`,\n    `CREATE INDEX IF NOT EXISTS "ReelCommentLike_commentId_createdAt_idx" ON "ReelCommentLike"("commentId","createdAt")`,\n'''
if needle not in s: raise SystemExit('schema needle not found')
s=s.replace(needle, needle+insert)

# 3) Replace post comment routes.
old="""app.patch('/api/posts/comments/:id',auth,async(req,res)=>{const c=await prisma.comment.findUnique({where:{id:req.params.id}});if(!c||c.authorId!==req.user.id)return res.status(403).json({error:'FORBIDDEN'});if(c.editCount>=1||Date.now()-c.createdAt.getTime()>5*60*1000)return res.status(400).json({error:'COMMENT_EDIT_WINDOW_EXPIRED'});const body=String(req.body.body||'').trim();if(!body)return res.status(400).json({error:'EMPTY_COMMENT'});const out=await prisma.comment.update({where:{id:c.id},data:{body:body.slice(0,1000),editedAt:new Date(),editCount:{increment:1}}});res.json(out)});\napp.delete('/api/posts/comments/:id',auth,async(req,res)=>{const c=await prisma.comment.findUnique({where:{id:req.params.id},include:{post:true}});if(!c)return res.status(404).json({error:'NOT_FOUND'});if(c.authorId!==req.user.id&&c.post.authorId!==req.user.id)return res.status(403).json({error:'FORBIDDEN'});await prisma.comment.delete({where:{id:c.id}});res.json({ok:true})});\n\napp.post('/api/posts/:id/comments',auth,async(req,res)=>{const body=String(req.body.body||'').trim();if(!body)return res.status(400).json({error:'EMPTY_COMMENT'});const p=await prisma.post.findUnique({where:{id:req.params.id}});if(!p)return res.status(404).json({error:'NOT_FOUND'});const c=await prisma.comment.create({data:{postId:p.id,authorId:req.user.id,body},include:{author:true}});if(p.authorId!==req.user.id)await prisma.notification.create({data:{userId:p.authorId,type:'COMMENT',text:'تم التعليق على منشورك'}});await notifyMentions(body,'تمت الإشارة إليك في تعليق على منشور');res.status(201).json({...c,author:safe(c.author)})});\napp.get('/api/posts/:id/comments',auth,async(req,res)=>{const rows=await prisma.comment.findMany({where:{postId:req.params.id},orderBy:{createdAt:'asc'},take:200,include:{author:true}});res.json(rows.map(c=>({...c,author:safe(c.author)})));});"""
new="""app.patch('/api/posts/comments/:id',auth,async(req,res)=>{const c=await prisma.comment.findUnique({where:{id:req.params.id}});if(!c||c.authorId!==req.user.id)return res.status(403).json({error:'FORBIDDEN'});if(c.editCount>=1||Date.now()-c.createdAt.getTime()>5*60*1000)return res.status(400).json({error:'COMMENT_EDIT_WINDOW_EXPIRED'});const body=String(req.body.body||'').trim();if(!body)return res.status(400).json({error:'EMPTY_COMMENT'});const out=await prisma.comment.update({where:{id:c.id},data:{body:body.slice(0,1000),editedAt:new Date(),editCount:{increment:1}}});res.json(out)});\napp.delete('/api/posts/comments/:id',auth,async(req,res)=>{const c=await prisma.comment.findUnique({where:{id:req.params.id},include:{post:true}});if(!c)return res.status(404).json({error:'NOT_FOUND'});if(c.authorId!==req.user.id&&c.post.authorId!==req.user.id)return res.status(403).json({error:'FORBIDDEN'});await prisma.comment.delete({where:{id:c.id}});res.json({ok:true})});\napp.post('/api/posts/comments/:id/like',auth,async(req,res)=>{const id=req.params.id;const c=await prisma.comment.findUnique({where:{id},select:{id:true,authorId:true,adminLikes:true}});if(!c)return res.status(404).json({error:'NOT_FOUND'});const key={commentId:id,userId:req.user.id};const old=await prisma.commentLike.findUnique({where:{commentId_userId:key}});if(old)await prisma.commentLike.delete({where:{commentId_userId:key}});else{await prisma.commentLike.create({data:key});if(c.authorId!==req.user.id)await prisma.notification.create({data:{userId:c.authorId,type:'LIKE',text:'أعجب شخص بتعليقك'}}).catch(()=>{});}const likes=await prisma.commentLike.count({where:{commentId:id}});res.json({liked:!old,likeCount:likes+Number(c.adminLikes||0)});});\napp.post('/api/posts/:id/comments',auth,async(req,res)=>{const body=String(req.body.body||'').trim();if(!body)return res.status(400).json({error:'EMPTY_COMMENT'});const p=await prisma.post.findUnique({where:{id:req.params.id}});if(!p)return res.status(404).json({error:'NOT_FOUND'});const parentId=String(req.body.parentId||'').trim()||null;const c=await prisma.comment.create({data:{postId:p.id,authorId:req.user.id,body:body.slice(0,1000),parentId},include:{author:true}});if(p.authorId!==req.user.id)await prisma.notification.create({data:{userId:p.authorId,type:'COMMENT',text:'تم التعليق على منشورك'}});await notifyMentions(body,'تمت الإشارة إليك في تعليق على منشور');res.status(201).json({...c,author:safe(c.author),likeCount:Number(c.adminLikes||0),likedByMe:false});});\napp.get('/api/posts/:id/comments',auth,async(req,res)=>{const rows=await prisma.comment.findMany({where:{postId:req.params.id},take:200,include:{author:true,likes:true},orderBy:[{adminLikes:'desc'},{createdAt:'asc'}]});res.json(rows.map(c=>({...c,author:safe(c.author),likeCount:c.likes.length+Number(c.adminLikes||0),likedByMe:c.likes.some(x=>x.userId===req.user.id)})));});"""
if old not in s: raise SystemExit('post comment block not found')
s=s.replace(old,new)

