# 5) Admin comments endpoint and boost hearts endpoint. Replace existing admin comments route.
old="app.get('/api/admin/comments',auth,admin,async(req,res)=>{const rows=await prisma.comment.findMany({orderBy:{createdAt:'desc'},take:300,include:{author:true,post:true}});res.json(rows.map(c=>({...c,author:safe(c.author)})));});"
new="""app.get('/api/admin/comments',auth,admin,async(req,res)=>{const kind=String(req.query.kind||'ALL').toUpperCase();const out=[];if(kind==='ALL'||kind==='POST'){const rows=await prisma.comment.findMany({orderBy:{createdAt:'desc'},take:300,include:{author:true,post:true,likes:true}});out.push(...rows.map(c=>({...c,kind:'POST',author:safe(c.author),likeCount:c.likes.length+Number(c.adminLikes||0)})));}if(kind==='ALL'||kind==='REEL'){const rows=await prisma.reelComment.findMany({orderBy:{createdAt:'desc'},take:300,include:{author:true,reel:true,likes:true}});out.push(...rows.map(c=>({...c,kind:'REEL',author:safe(c.author),likeCount:c.likes.length+Number(c.adminLikes||0)})));}out.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));res.json(out.slice(0,500));});\napp.post('/api/admin/comments/:kind/:id/boost',auth,requirePermission('comments.manage'),async(req,res)=>{try{const kind=String(req.params.kind||'').toUpperCase();const delta=Number(req.body?.hearts||0);if(!['POST','REEL'].includes(kind)||!Number.isInteger(delta)||delta===0||Math.abs(delta)>10000000)return res.status(400).json({error:'INVALID_HEART_DELTA'});let row;if(kind==='POST'){row=await prisma.comment.findUnique({where:{id:req.params.id}});if(!row)return res.status(404).json({error:'NOT_FOUND'});const next=Math.max(0,Number(row.adminLikes||0)+delta);row=await prisma.comment.update({where:{id:row.id},data:{adminLikes:next},include:{author:true,likes:true}});await auditAction(req,delta>0?'ADMIN_COMMENT_HEARTS_ADDED':'ADMIN_COMMENT_HEARTS_REMOVED',{permission:'comments.manage',targetId:row.id,targetType:'COMMENT',after:{kind,delta,adminLikes:next}});return res.json({...row,kind,author:safe(row.author),likeCount:row.likes.length+next});}row=await prisma.reelComment.findUnique({where:{id:req.params.id}});if(!row)return res.status(404).json({error:'NOT_FOUND'});const next=Math.max(0,Number(row.adminLikes||0)+delta);row=await prisma.reelComment.update({where:{id:row.id},data:{adminLikes:next},include:{author:true,likes:true}});await auditAction(req,delta>0?'ADMIN_COMMENT_HEARTS_ADDED':'ADMIN_COMMENT_HEARTS_REMOVED',{permission:'comments.manage',targetId:row.id,targetType:'REEL_COMMENT',after:{kind,delta,adminLikes:next}});res.json({...row,kind,author:safe(row.author),likeCount:row.likes.length+next});}catch(e){res.status(400).json({error:'COMMENT_HEART_UPDATE_FAILED'});}});"""
if old not in s: raise SystemExit('admin comments route not found')
s=s.replace(old,new)

# 6) Add achievements endpoint before creator milestones section.
marker='// ---- Creator milestones & rewards ----------------------------------------\n'
endpoint="""// ---- Achievements / tasks --------------------------------------------------\napp.get('/api/achievements',auth,async(req,res)=>{\n  const userId=req.user.id;\n  const [u,followers,following,posts,reels,comments,reelComments,lives,postLikes,reelLikes]=await Promise.all([\n    prisma.user.findUnique({where:{id:userId},select:{demoFollowersCount:true}}),\n    prisma.follow.count({where:{followingId:userId}}),\n    prisma.follow.count({where:{followerId:userId}}),\n    prisma.post.count({where:{authorId:userId}}),\n    prisma.reel.count({where:{authorId:userId}}),\n    prisma.comment.count({where:{authorId:userId}}),\n    prisma.reelComment.count({where:{authorId:userId}}),\n    prisma.liveRoom.count({where:{hostId:userId}}),\n    prisma.like.count({where:{post:{authorId:userId}}}),\n    prisma.reelLike.count({where:{reel:{authorId:userId}}}),\n  ]);\n  const followerCount=followers+Number(u?.demoFollowersCount||0);\n  const tasks=[\n    {id:'followers_100',title:'أول 100 متابع',description:'وصل إلى 100 متابع',target:100,progress:followerCount,rewardCoins:50,icon:'groups'},\n    {id:'followers_500',title:'صانع المجتمع',description:'وصل إلى 500 متابع',target:500,progress:followerCount,rewardCoins:150,icon:'groups'},\n    {id:'followers_1000',title:'مبدع مؤثر',description:'وصل إلى 1,000 متابع',target:1000,progress:followerCount,rewardCoins:300,icon:'verified'},\n    {id:'posts_10',title:'صانع المحتوى',description:'انشر 10 منشورات',target:10,progress:posts,rewardCoins:75,icon:'post'},\n    {id:'reels_10',title:'نجم Reels',description:'انشر 10 Reels',target:10,progress:reels,rewardCoins:100,icon:'movie'},\n    {id:'comments_25',title:'صوت المجتمع',description:'اكتب 25 تعليقًا',target:25,progress:comments+reelComments,rewardCoins:75,icon:'comment'},\n    {id:'live_3',title:'صاحب البث',description:'ابدأ 3 بثوث مباشرة',target:3,progress:lives,rewardCoins:150,icon:'live'},\n    {id:'likes_100',title:'محبوب المجتمع',description:'احصل على 100 إعجاب على محتواك',target:100,progress:postLikes+reelLikes,rewardCoins:200,icon:'heart'},\n    {id:'following_50',title:'شبكة واسعة',description:'تابع 50 حسابًا',target:50,progress:following,rewardCoins:50,icon:'people'},\n  ];\n  const newlyGranted=await grantCreatorMilestones(userId).catch(()=>[]);\n  res.json({followers:followerCount,tasks:tasks.map(x=>({...x,completed:x.progress>=x.target,ratio:x.target?Math.min(1,x.progress/x.target):1})),newlyGranted:newlyGranted.map(m=>({title:m.title,rewardCoins:m.rewardCoins,rewardGiftSlug:m.rewardGiftSlug,followersRequired:m.followersRequired}))});\n});\n\n"""
if marker not in s: raise SystemExit('marker not found')
s=s.replace(marker, endpoint+marker)

p.write_text(s)
